using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis.Text;

namespace CodeShield.CSharp.Building;

/// <summary>Generated-file rules: obj/ folders, well-known suffixes, or an auto-generated header.</summary>
internal static partial class GeneratedFiles
{
    private static readonly string[] Suffixes = [".g.cs", ".generated.cs", ".designer.cs"];
    private const int HeaderLines = 20;

    public static bool IsGenerated(string path, SourceText text) =>
        IsGeneratedPath(path) || HasGeneratedHeader(text);

    public static bool IsGeneratedPath(string path)
    {
        var segments = path.Replace('\\', '/').Split('/');
        return segments.Take(segments.Length - 1).Any(segment => segment.Equals("obj", StringComparison.OrdinalIgnoreCase))
            || Suffixes.Any(suffix => segments[^1].EndsWith(suffix, StringComparison.OrdinalIgnoreCase));
    }

    private static bool HasGeneratedHeader(SourceText text) =>
        text.Lines.Take(HeaderLines).Any(line => AutoGenerated().IsMatch(line.ToString()));

    [GeneratedRegex("<auto-generated", RegexOptions.IgnoreCase)]
    private static partial Regex AutoGenerated();
}
